function parkKey(p){return 'park:'+p.id;}
function parkUrl(p){return 'japon_cartes_voiture.html?park='+encodeURIComponent(p.id);}
function parkCard(p){return `<article class="card park-shortcard"><div class="card-top">${badge('Voiture · '+esc(p.region))}${star(parkKey(p),p.name)}</div><h3>${esc(p.name)}</h3><p class="muted">${esc(p.city)} · ${esc(p.region)}</p><p class="park-price">${esc(p.price)} <small>tarif historique</small></p>${p.warning?'<p class="park-warning">⚠️ '+esc(p.warning)+'</p>':''}<p class="muted">${p.locationVerified?'Adresse publiée, entrée GPS non confirmée.':'Adresse exacte non confirmée.'} Les épingles sont approximatives.</p><div class="links"><a href="${esc(parkUrl(p))}" target="_blank" rel="noopener noreferrer">Voir cette fiche sur la carte ↗</a>${ext(p.source,'Fiche source')}</div></article>`}
function star(id,n){return `<button class="save" data-save="${id}" aria-label="Favori : ${esc(n)}" aria-pressed="${favorites.has(id)}">${favorites.has(id)?'★':'☆'}</button>`}
function heading(t){return `<div class="section-head"><h2>${t}</h2></div>`}
function table(head,rows){return `<div class="table-scroll" role="region" aria-label="Tableau défilant" tabindex="0"><table><thead><tr>${head.map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
